cd ~/claude-browser && cat > /tmp/atsne-inter.mjs <<'EOF'
import { chromium } from "playwright";
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1440, height: 900 } });
const fehler = [];
p.on("pageerror", (e) => fehler.push(String(e)));
await p.goto("http://localhost:3100/at/rechner/gewerbestrom-check", { waitUntil: "networkidle" });
await p.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 5000 }).catch(() => {});
await p.fill("#at-leistung", "100");
await p.waitForTimeout(400);
const h = await p.locator("text=Benutzungsstunden").count();
const txt = await p.locator("[data-rechner]").innerText();
console.log("Benutzungsstunden sichtbar:", h > 0, "| 2500 h:", /2\.?500\s*h/.test(txt));
await p.fill("#at-leistung", "5");
await p.waitForTimeout(400);
const warn = await p.locator("text=8.760").count();
console.log("Unplausibel-Warnung:", warn > 0, "| Seitenfehler:", fehler.length);
await b.close();
EOF
MSYS_NO_PATHCONV=1 node /tmp/atsne-inter.mjs

